<template><AssetListShell title="Published Content" description="查看实际发布版本、表现数据与复盘结果" :account-ref="store.account_ref" :items="items" :loading="loading" :error="error" :page-no="pageNo" :page-size="pageSize" :total="total" @page-change="load"><template #default="{ item }"><button class="asset-row" @click="router.push({ name: 'agentPublication', params: { publishedNoteRef: item.ref } })"><span><strong>{{ item.title }}</strong><small>实际发布 {{ item.version_number ? `V${item.version_number}` : '版本未知' }} · 发布于 {{ formatTime(item.published_at) }}</small></span><el-tag type="success">{{ statusLabel(item.status) }}</el-tag></button></template></AssetListShell></template>
<script setup lang="ts">
import { onBeforeUnmount,onMounted,ref } from 'vue';import { useRouter } from 'vue-router';import AssetListShell from '@/components/AssetListShell.vue';import { getPublicationList } from '@/api/unifiedAgent';import { useAgentChatStore } from '@/stores/agentChat';import type { PublicationSummary } from '@/types/productRead'
import { formatTime, statusLabel } from '@/utils/presentation'
const store=useAgentChatStore(),router=useRouter(),items=ref<PublicationSummary[]>([]),loading=ref(false),error=ref(''),pageNo=ref(1),pageSize=20,total=ref(0);let controller:AbortController|null=null
async function load(page=1){if(!store.account_ref)return;controller?.abort();controller=new AbortController();loading.value=true;error.value='';try{const result=await getPublicationList(store.account_ref,page,pageSize,controller.signal);items.value=result.items;total.value=result.total;pageNo.value=result.page_no}catch(reason){if((reason as Error).name!=='CanceledError')error.value='Published Content 列表加载失败'}finally{loading.value=false}}
onMounted(()=>load());onBeforeUnmount(()=>controller?.abort())
</script>
